window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[360]={"id":"360","numero":360,"titre":"Pneumothorax","objectifs":[{"id":"360-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition du pneumothorax","contenu":"<p>Le <span class=\"kw-def\">pneumothorax</span> (PNO) est défini par la <span class=\"kw-def\">présence d'air dans l'espace pleural</span> — un <span class=\"kw-imagerie\">épanchement pleural</span> gazeux — entraînant un <span class=\"kw-clinique\">collapsus</span> partiel ou complet du poumon. En cas de <span class=\"kw-imagerie\">pneumothorax</span>, le poumon se <strong>désolidarise de la paroi thoracique</strong> et se <strong>rétracte sur le hile</strong>.</p>\n      <p>Rappel anatomique — la <span class=\"kw-def\">plèvre</span> est une séreuse comprenant, en continuité :</p>\n      <ul>\n        <li>le <span class=\"kw-def\">feuillet pariétal</span> (costal, diaphragmatique et médiastinal), qui tapisse le contenant de la cage thoracique et le médiastin ;</li>\n        <li>le <span class=\"kw-def\">feuillet viscéral</span>, qui tapisse le poumon ;</li>\n        <li>l'<span class=\"kw-def\">espace pleural</span> entre ces deux feuillets, rendu <strong>virtuel</strong> par la pression négative (« vide pleural ») qui y règne et qui assure le maintien de l'expansion pulmonaire.</li>\n      </ul>","frequence":0},{"id":"360-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie des pneumothorax primitifs et secondaires","contenu":"<p>Selon le mécanisme, on distingue le <span class=\"kw-imagerie\">pneumothorax</span> <strong>spontané</strong> (primaire ou secondaire) du <span class=\"kw-imagerie\">pneumothorax</span> traumatique. <span class=\"kw-clinique\">Les</span> deux formes spontanées diffèrent par l'<span class=\"kw-etio\">état du poumon sous-jacent</span>.</p>\n      <table >\n        <thead>\n          <tr><th></th><th>PNO spontané primaire (PSP)</th><th>PNO spontané secondaire (PSS)</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Poumon sous-jacent</td>\n            <td>Poumon <strong>en apparence sain</strong></td>\n            <td>Poumon <span class=\"kw-alerte\">pathologique</span></td>\n          </tr>\n          <tr>\n            <td>Mécanisme</td>\n            <td><span class=\"kw-def\">Lésions microscopiques</span> rendant la plèvre <strong>poreuse</strong></td>\n            <td><span class=\"kw-alerte\">Rupture</span>, dans la cavité pleurale, d'une <span class=\"kw-clinique\">lésion</span> parenchymateuse</td>\n          </tr>\n          <tr>\n            <td>Lésions en cause</td>\n            <td>Anomalies infracliniques de la plèvre (porosité)</td>\n            <td><strong><span class=\"kw-clinique\">Bulle</span> :</strong> <span class=\"kw-etio\">emphysème</span><br><strong>Lésions kystiques ou nécrosantes :</strong> <span class=\"kw-etio\">mucoviscidose</span> ; <span class=\"kw-etio\">fibroses pulmonaires</span> ; <span class=\"kw-etio\">tuberculose</span> (séquelles)<br><strong>Autres :</strong> <span class=\"kw-etio\">PID</span> ; pathologies <span class=\"kw-etio\">néoplasiques</span> ; <span class=\"kw-etio\">pneumocystose</span> ; <span class=\"kw-etio\">pneumonie abcédée</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Le <span class=\"kw-def\">pneumothorax traumatique</span> relève d'un mécanisme distinct : une <span class=\"kw-etio\">effraction de la plèvre viscérale</span> d'origine <span class=\"kw-etio\">iatrogène</span> ou traumatique (voir l'objectif étiologique).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 209 — <span class=\"kw-def\">BPCO</span> · 210 — Pneumopathie interstitielle diffuse · 159 — <span class=\"kw-def\">Tuberculose</span> Enfant / Adulte · 188 — <span class=\"kw-def\">Asthme</span> - Rhinite</em></p>","frequence":2},{"id":"360-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments du diagnostic positif et du diagnostic différentiel d’un pneumothorax","contenu":"<p>Le diagnostic de <span class=\"kw-imagerie\">pneumothorax</span> repose sur la <strong>clinique</strong> et la <strong><span class=\"kw-imagerie\">radiographie thoracique</span></strong>. Le tableau peut être bruyant ou, au contraire, totalement <span class=\"kw-clinique\">asymptomatique</span>.</p>\n      <p><strong>Signes fonctionnels</strong> :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Douleur thoracique</span> : début <strong>brutal</strong>, souvent <strong>au repos</strong>, type <span class=\"kw-clinique\">coup de poignard</span>, homolatérale au PNO (latéro-thoracique, basi-thoracique ou postérieure), <strong>rythmée par la respiration</strong> (majorée à l'inspiration et à la <span class=\"kw-clinique\">toux</span>) et au changement de position ; elle s'estompe souvent rapidement.</li>\n        <li><span class=\"kw-clinique\">Dyspnée</span> : inconstante, d'intensité variable.</li>\n        <li><span class=\"kw-clinique\">Toux sèche irritative</span>.</li>\n      </ul>\n      <p><strong>Signes physiques</strong> — syndrome d'épanchement gazeux, à rechercher temps par temps :</p>\n      <table >\n        <thead>\n          <tr><th>Temps de l'examen</th><th>Signe</th></tr>\n        </thead>\n        <tbody>\n          <tr><td>Inspection</td><td>Hémithorax normal, ou <span class=\"kw-clinique\">distendu et moins mobile</span> (diminution de l'ampliation thoracique)</td></tr>\n          <tr><td>Palpation</td><td><span class=\"kw-clinique\">Abolition des vibrations vocales</span> ; <span class=\"kw-clinique\">emphysème sous-cutané</span> (rare)</td></tr>\n          <tr><td>Percussion</td><td><span class=\"kw-clinique\">Tympanisme</span></td></tr>\n          <tr><td>Auscultation</td><td>Diminution ou <span class=\"kw-clinique\">abolition du murmure vésiculaire</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Facteurs favorisants</strong> à rechercher à l'interrogatoire :</p>\n      <ul>\n        <li><span class=\"kw-etio\">ATCD de pneumothorax</span> : argument fort, la récidive survenant dans près d'<span class=\"kw-chiffre\">1/3</span> des cas.</li>\n        <li><span class=\"kw-etio\">Tabagisme actif</span>.</li>\n        <li>Efforts inspiratoires lors du <span class=\"kw-etio\">sniff de cocaïne</span>.</li>\n        <li>Vols aériens et plongée subaquatique : ils ne créent <strong>pas</strong> de PNO de novo, mais <span class=\"kw-alerte\">majorent un PNO préexistant</span>.</li>\n      </ul>\n      <p><strong><span class=\"kw-def\">Diagnostic différentiel</span></strong> : écarter <span class=\"kw-clinique\">les</span> autres causes de <span class=\"kw-clinique\">douleur thoracique</span> et de <span class=\"kw-clinique\">dyspnée</span>. Le différentiel le plus difficile est représenté par les <span class=\"kw-alerte\">bulles géantes d'emphysème</span> chez un <span class=\"kw-def\">BPCO</span> sévère, qui peuvent être prises à tort pour un PNO.</p>\n      <p>La <span class=\"kw-bio\">gazométrie</span> artérielle, lorsqu'elle est réalisée, montre souvent une <span class=\"kw-bio\">hypoxémie</span> associée à une <span class=\"kw-bio\">hypocapnie</span> (effet shunt).</p>\n      <div class=\"callout callout-warn\">⚠️ <strong>Piège classique.</strong> Devant une hyperclarté chez un <span class=\"kw-def\">BPCO</span> sévère, ne pas confondre une <span class=\"kw-alerte\">bulle géante d'emphysème</span> avec un <span class=\"kw-imagerie\">pneumothorax</span> : rechercher le <span class=\"kw-imagerie\">signe du raccordement</span> sur la <span class=\"kw-imagerie\">radiographie</span> et la <span class=\"kw-imagerie\">TDM</span> thoracique avant tout <span class=\"kw-ttt\">drainage</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 206 — Epanchement pleural · 209 — <span class=\"kw-def\">BPCO</span></em></p>","frequence":5},{"id":"360-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la sémiologie radiologique du pneumothorax","contenu":"<p><strong>Modalités</strong> — la <span class=\"kw-imagerie\"><span class=\"kw-imagerie\">radiographie</span> thoracique</span> est réalisée <strong>de face</strong>, <strong>debout</strong>, en <span class=\"kw-imagerie\">inspiration</span>.</p>\n      <div class=\"callout callout-warn\">⚠️ <strong>Réglementaire.</strong> La <span class=\"kw-imagerie\">radiographie</span> de face <span class=\"kw-alerte\">en expiration ne doit plus être réalisée</span> — sans bénéfice diagnostique démontré, voire dangereuse.</div>\n      <table >\n        <thead>\n          <tr><th>Forme</th><th>Sémiologie radiologique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>PNO incomplet</td>\n            <td><span class=\"kw-radio\">Hyperclarté</span> avec disparition du parenchyme pulmonaire, prédominant en <strong>apical</strong></td>\n          </tr>\n          <tr>\n            <td>PNO complet</td>\n            <td><span class=\"kw-radio\">Rétraction du parenchyme</span> pulmonaire autour du hile ; <span class=\"kw-radio\">abaissement de la coupole diaphragmatique</span> homolatérale ; <span class=\"kw-radio\">élargissement des espaces intercostaux</span> ; réaction liquidienne de faible volume possible</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Signes de gravité</span> radiologique</td>\n            <td><span class=\"kw-alerte\">Refoulement controlatéral du médiastin</span> ; <span class=\"kw-alerte\">hyperclarté bilatérale</span> ; <span class=\"kw-alerte\">bride</span> (risque <span class=\"kw-etio\">hémorragique</span>) ; <span class=\"kw-alerte\">niveau liquidien</span> (risque d'hémopneumothorax) ; anomalie du parenchyme pulmonaire sous-jacent</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Autres examens d'imagerie</strong> :</p>\n      <ul>\n        <li><span class=\"kw-imagerie\">TDM thoracique</span> non injectée (non systématique) : indiquée en cas de doute radiologique, de forme secondaire ou de forme traumatique.</li>\n        <li><span class=\"kw-imagerie\">Échographie pleurale</span> : permet le diagnostic immédiat d'un <span class=\"kw-imagerie\">pneumothorax</span> au lit du patient.</li>\n      </ul>","frequence":3},{"id":"360-5","rang":"A","rubrique":"Contenu multimédia","titre":"Radiographie de face d’un pneumothorax spontané d’abondance moyenne","contenu":"<p>Cet objectif attend la <strong>lecture commentée d'une <span class=\"kw-imagerie\">radiographie</span> de face</strong> montrant un <span class=\"kw-imagerie\">pneumothorax</span> spontané d'<strong>abondance moyenne</strong>. Sémiologie attendue :</p>\n      <ul>\n        <li><span class=\"kw-radio\">Hyperclarté</span> de l'hémithorax avec disparition de la trame vasculaire pulmonaire en périphérie.</li>\n        <li><span class=\"kw-radio\">Ligne pleurale</span> visible, matérialisant la limite externe du poumon partiellement collabé.</li>\n        <li>Décollement d'abondance moyenne, à <strong>prédominance apicale</strong>.</li>\n      </ul>\n      <p>Repère métrique — un <span class=\"kw-imagerie\">pneumothorax</span> de « grande taille » est arbitrairement défini par un <span class=\"kw-chiffre\">décollement sur toute la hauteur de la ligne axillaire</span>, d'une <span class=\"kw-chiffre\">largeur ≥ 2 cm</span> au niveau du hile.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/360/rxt-pneumothorax-abondance-moyenne.png\" alt=\"Radiographie de thorax de face : pneumothorax droit d'abondance moyenne, croissant clair avasculaire périphérique et ligne pleurale bordante\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">RX</span> de thorax de face — <span class=\"kw-def\">pneumothorax</span> droit d'<strong>abondance moyenne</strong> : <span class=\"kw-radio\">croissant clair avasculaire périphérique</span> et <span class=\"kw-radio\">ligne pleurale bordante</span> (plèvre viscérale décollée de la plèvre pariétale). Source : banque iconographique officielle EDN (« Imagerie à connaître »).</figcaption>\n      </figure>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/pneumothorax","label":"Radiopaedia : Pneumothorax"},{"href":"https://radiopaedia.org/articles/pneumomediastinum","label":"Radiopaedia : Pneumomediastinum"}]},{"id":"360-6","rang":"A","rubrique":"Contenu multimédia","titre":"Radiographie de thorax d’un pneumothorax complet","contenu":"<p>Cet objectif attend la <strong>lecture commentée d'une <span class=\"kw-imagerie\">radiographie</span> de thorax</strong> montrant un <span class=\"kw-imagerie\">pneumothorax</span> <strong>complet</strong>. Sémiologie attendue :</p>\n      <ul>\n        <li>Poumon entièrement <span class=\"kw-clinique\">collabé</span>, <span class=\"kw-radio\">rétracté en moignon autour du hile</span>.</li>\n        <li><span class=\"kw-radio\">Hyperclarté</span> de l'ensemble de l'hémithorax.</li>\n        <li><span class=\"kw-radio\">Abaissement de la coupole diaphragmatique</span> homolatérale.</li>\n        <li><span class=\"kw-radio\">Élargissement des espaces intercostaux</span>.</li>\n      </ul>\n      <p>Vérifier systématiquement l'absence de <span class=\"kw-alerte\">signe de gravité radiologique</span>, notamment un refoulement controlatéral du médiastin.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/360/rxt-pneumothorax-complet.png\" alt=\"Radiographie de thorax de face : pneumothorax droit complet compressif, poumon rétracté au hile et déviation médiastinale controlatérale\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">RX</span> de thorax de face — <span class=\"kw-def\">pneumothorax</span> droit <strong>complet compressif</strong> : <span class=\"kw-radio\">hyperclarté diffuse de l'hémithorax</span>, <span class=\"kw-radio\">poumon entièrement décollé rétracté au hile</span> et <span class=\"kw-alerte\">déviation médiastinale controlatérale</span> (<span class=\"kw-alerte\">signe de gravité</span>). Source : banque iconographique officielle EDN (« Imagerie à connaître »).</figcaption>\n      </figure>","frequence":2},{"id":"360-7","rang":"A","rubrique":"Étiologies","titre":"Connaître les éléments du diagnostic étiologique d’un pneumothorax : pneumothorax traumatique, pneumothorax spontané primaire, pneumothorax spontané secondaire","contenu":"<p>Le <span class=\"kw-def\">diagnostic étiologique</span> distingue <strong>trois grandes situations</strong>, chacune ayant son <span class=\"kw-def\">terrain</span> et ses causes propres.</p>\n      <table >\n        <thead>\n          <tr><th>Type</th><th>Terrain</th><th>Causes / mécanisme</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>PNO spontané primaire (PSP)</td>\n            <td>Adulte <span class=\"kw-chiffre\">&lt; 35 ans</span> ; prédominance <strong>masculine</strong> ; sujet <strong>longiligne et de grande taille</strong> ; <span class=\"kw-etio\">tabagisme</span> (fumeur dans <span class=\"kw-chiffre\">¾</span> des cas)</td>\n            <td>Poumon en apparence sain ; <span class=\"kw-def\">lésions microscopiques</span> rendant la plèvre poreuse</td>\n          </tr>\n          <tr>\n            <td>PNO spontané secondaire (PSS)</td>\n            <td>Patients <span class=\"kw-etio\">BPCO</span> ++ ; plus rarement <span class=\"kw-etio\">asthmatiques</span> ou atteints de <span class=\"kw-etio\">mucoviscidose</span></td>\n            <td><span class=\"kw-alerte\">Rupture</span> sur poumon pathologique : <span class=\"kw-clinique\">bulle</span> d'<span class=\"kw-etio\">emphysème</span> ; lésions kystiques ou nécrosantes ; PID ; pathologies néoplasiques ; pneumocystose ; <span class=\"kw-def\">pneumonie</span> abcédée</td>\n          </tr>\n          <tr>\n            <td>PNO traumatique</td>\n            <td>Tout contexte traumatique ou de geste invasif thoracique</td>\n            <td><strong><span class=\"kw-etio\">Iatrogène</span> :</strong> <span class=\"kw-ttt\">ponction</span> trans-thoracique ; ponction pleurale ; <span class=\"kw-etio\">voie veineuse centrale</span> (jugulaire ou sous-clavière) ; cœlioscopie<br><strong>Traumatisme ouvert :</strong> arme blanche ; arme à feu<br><strong>Traumatisme fermé :</strong> <span class=\"kw-etio\">côte fracturée</span> ++ ; <span class=\"kw-etio\">blast pulmonaire</span> (onde de <span class=\"kw-alerte\">choc</span> → hyperpression thoracique → ruptures alvéolaires)</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 334 — PEC immédiate trauma : polytraumatisme, brûlure, <span class=\"kw-clinique\">hypothermie</span>… · 337 — Intoxication aiguë</em></p>","frequence":1},{"id":"360-8","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les éléments du diagnostic de gravité d’un pneumothorax","contenu":"<div class=\"callout callout-danger\">⚠️ <strong>Point clé.</strong> La gravité d'un <span class=\"kw-imagerie\">pneumothorax</span> est <span class=\"kw-alerte\">clinique</span> : un <span class=\"kw-def\">PNO grave</span> se définit par une <span class=\"kw-alerte\">dyspnée sévère</span> et/ou un <span class=\"kw-alerte\">collapsus tensionnel</span>. Elle <strong>ne dépend pas</strong> de l'importance du décollement pleural sur la <span class=\"kw-imagerie\">radiographie</span>.</div>\n      <p><strong><span class=\"kw-alerte\">Signes de gravité</span> cliniques</strong> :</p>\n      <ul>\n        <li><span class=\"kw-alerte\">Hypotension</span> (PAS <span class=\"kw-chiffre\">≤ 90 mmHg</span>).</li>\n        <li><span class=\"kw-alerte\">Tachycardie ≥ 120 bpm</span>, ou <span class=\"kw-alerte\">bradycardie</span> (gravité extrême).</li>\n        <li><span class=\"kw-alerte\">Désaturation</span>, <span class=\"kw-alerte\">détresse respiratoire</span>.</li>\n        <li><span class=\"kw-alerte\">Signes droits</span> : <span class=\"kw-clinique\">hypotension</span> artérielle + <span class=\"kw-clinique\">turgescence jugulaire</span>, signant la <span class=\"kw-alerte\">défaillance</span> cardiaque droite.</li>\n        <li><span class=\"kw-alerte\">Déviation de la pointe du cœur</span> (déplacement médiastinal).</li>\n        <li><span class=\"kw-alerte\">Arrêt cardiaque</span> au maximum.</li>\n      </ul>\n      <p><strong><span class=\"kw-alerte\"><span class=\"kw-def\">Critères de</span> gravité</span> liés au <span class=\"kw-def\">terrain</span> / contexte</strong> : caractère <span class=\"kw-alerte\">bilatéral</span> ; survenue sur <span class=\"kw-alerte\">poumon unique</span> ; survenue <span class=\"kw-alerte\">sous ventilation</span> invasive ou non invasive ; <span class=\"kw-alerte\">insuffisance respiratoire chronique</span> sous-jacente.</p>\n      <p><strong>PNO compressif</strong> — mécanisme de la forme la plus grave : une <span class=\"kw-def\">fistule broncho-pleurale</span> réalise une <span class=\"kw-alerte\">valve unidirectionnelle</span> (l'<span class=\"kw-def\">air</span> entre dans la plèvre à l'inspiration mais n'en ressort pas à l'expiration). La pression pleurale devient positive et gêne le retour veineux (« <span class=\"kw-alerte\">tamponnade gazeuse</span> ») : chute tensionnelle + signes d'<span class=\"kw-def\">insuffisance cardiaque</span> droite.</p>\n      <p><strong>PNO sous <span class=\"kw-ttt\">ventilation mécanique</span></strong> — y penser systématiquement chez un patient de <span class=\"kw-alerte\">réanimation</span> devant : toute augmentation brutale des pressions d'insufflation du respirateur ; tout collapsus brutal sous ventilation assistée (PNO compressif) ; au décours d'une tentative de pose de voie veineuse sous-clavière.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 359 — <span class=\"kw-alerte\">Détresse</span> et <span class=\"kw-ci\">insuffisance respiratoire</span> aiguë · 332 — Etat de <span class=\"kw-alerte\">choc</span> · 331 — Arrêt cardio-circulatoire · 208 — Insuffisance respiratoire chronique</em></p>","frequence":1},{"id":"360-9","rang":"A","rubrique":"Prise en charge","titre":"Connaître les grands principes de l’exsufflation pleurale et ses indications","contenu":"<p>Le choix du traitement repose sur <strong>trois questions</strong> : le PNO est-il <strong>bien toléré</strong> (<span class=\"kw-clinique\">dyspnée</span>, <span class=\"kw-bio\">SpO2</span>) ? Est-il de <strong>grande abondance</strong> (<span class=\"kw-chiffre\">≥ 2 cm</span>) ? Quelle est la <strong>cause / le <span class=\"kw-def\">terrain</span></strong> (PSP, PSS, traumatique) ?</p>\n      <table >\n        <thead>\n          <tr><th>Situation</th><th>PSP</th><th>PSS</th><th>PNO traumatique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>PNO bien toléré et de faible abondance</td>\n            <td><span class=\"kw-ttt\">Surveillance</span></td>\n            <td><span class=\"kw-ttt\">Drain</span> (sauf tout petit décollement)</td>\n            <td><span class=\"kw-ttt\">Surveillance</span> ; <span class=\"kw-ttt\">drain</span> si patient sous ventilation assistée</td>\n          </tr>\n          <tr>\n            <td>PNO mal toléré ou de grande abondance</td>\n            <td><span class=\"kw-ttt\">Exsufflation manuelle</span> ; <span class=\"kw-ttt\">drain</span> de petit calibre si échec</td>\n            <td><span class=\"kw-ttt\">Drain de petit calibre</span></td>\n            <td><span class=\"kw-ttt\">Drain</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Principe de l'exsufflation</strong> (= <span class=\"kw-ttt\">ponction</span>) — méthode bien tolérée, à durée d'<span class=\"kw-alerte\">hospitalisation</span> brève (réalisable en ambulatoire) :</p>\n      <ul>\n        <li>Anesthésie locale.</li>\n        <li>Petit cathéter introduit par la <span class=\"kw-ttt\">voie thoracique antérieure</span>, patient en position semi-assise ou en décubitus dorsal.</li>\n        <li><span class=\"kw-ttt\">Exsufflation manuelle</span> à la seringue de <span class=\"kw-chiffre\">50 mL</span>, ou système d'aspiration douce.</li>\n        <li>Cathéter retiré au terme de l'exsufflation ; résultat jugé sur la <span class=\"kw-imagerie\">radiographie de contrôle</span>.</li>\n      </ul>\n      <p><strong>Indications</strong> : selon le CEP, l'exsufflation est proposée comme seul traitement des <span class=\"kw-def\">PNO spontanés</span> ; selon le MIR, elle est indiquée en cas de <span class=\"kw-alerte\">mauvaise tolérance</span> ou de décollement <span class=\"kw-chiffre\">≥ 2 cm sur l'ensemble de la ligne axillaire</span>. Le taux de succès est de l'ordre de <span class=\"kw-chiffre\">50 %</span>, indépendant de la taille du PNO ; en cas d'échec, un drain pleural de petit calibre est posé en 2nde intention.</p>\n      <p><strong>Voies d'abord</strong> :</p>\n      <ul>\n        <li><strong>Voie antérieure :</strong> 2ᵉ ou 3ᵉ espace intercostal, en dehors de la ligne médio-claviculaire pour <span class=\"kw-alerte\">éviter l'artère mammaire interne</span>.</li>\n        <li><strong>Voie axillaire</strong> (triangle de sécurité) : 4ᵉ ou 5ᵉ espace intercostal, sur la ligne axillaire moyenne ; <span class=\"kw-ci\">ne jamais</span> piquer sous la ligne mamelonnaire (risque de <span class=\"kw-alerte\">plaie diaphragmatique</span> et de blessure d'organes abdominaux).</li>\n      </ul>\n      <div class=\"callout callout-warn\">⚠️ <strong>Repères à risque.</strong> Voie antérieure : rester en dehors de la ligne médio-claviculaire (<span class=\"kw-alerte\">artère mammaire interne</span>). Voie axillaire : ne pas descendre sous la ligne mamelonnaire (<span class=\"kw-alerte\">coupole diaphragmatique</span>).</div>","frequence":0},{"id":"360-10","rang":"B","rubrique":"Prise en charge","titre":"Connaître les grands principes du drainage pleural et ses indications","contenu":"<p>Le <span class=\"kw-ttt\">drainage pleural</span> évacue l'épanchement gazeux à l'aide d'un drain laissé en place. Le <strong>calibre du drain importe peu</strong> : il n'y a pas d'avantage démontré des drains de gros calibre.</p>\n      <p><strong>Modalités</strong> :</p>\n      <ul>\n        <li><span class=\"kw-ttt\">Drainage</span> <span class=\"kw-ttt\">percutané</span> (drain « en queue de cochon ») ou <span class=\"kw-ttt\">chirurgical</span> (poumon difficile à drainer).</li>\n        <li>Voie d'abord : antérieure ou axillaire (mêmes repères que pour l'exsufflation).</li>\n        <li>Évacuation de l'<span class=\"kw-def\">air</span>, selon deux modalités :\n          <ul>\n            <li><strong>Active :</strong> drain mis en <span class=\"kw-ttt\">aspiration douce</span> sur le bocal, entre <span class=\"kw-chiffre\">−5 et −20 mmHg</span>.</li>\n            <li><strong>Spontanée :</strong> drain relié à une <span class=\"kw-ttt\">valve unidirectionnelle</span> (valve anti-retour), ou à un bocal jouant le rôle de valve unidirectionnelle (<span class=\"kw-ttt\">siphonage</span>).</li>\n          </ul>\n        </li>\n        <li>Ablation du drain après <strong>réexpansion complète</strong> du poumon, en l'absence de fuite persistante, confirmée par une <span class=\"kw-imagerie\">radiographie de contrôle</span>.</li>\n      </ul>\n      <p><strong>Indications</strong> (cf. tableau de décision du traitement) : PNO spontané secondaire ; <span class=\"kw-imagerie\">pneumothorax</span> traumatique ; PNO mal toléré ou de grande abondance ; échec de l'exsufflation dans un PSP.</p>\n      <p>Hors <span class=\"kw-alerte\">urgence</span> immédiate, un <span class=\"kw-bio\">bilan d'hémostase</span> et un <span class=\"kw-bio\">groupe sanguin</span> sont réalisés avant le geste. Une <span class=\"kw-imagerie\">radiographie</span> de contrôle est systématique après <span class=\"kw-ttt\">ponction</span> ou drainage, pour vérifier l'absence de complication <span class=\"kw-etio\">iatrogène</span> et la bonne position du drain.</p>","frequence":4},{"id":"360-11","rang":"B","rubrique":"Prise en charge","titre":"Connaître les mesures de prévention des récidives de pneumothorax (arrêt du tabac, ± pleurodèse)","contenu":"<p>La récidive d'un <span class=\"kw-imagerie\">pneumothorax</span> spontané est fréquente, le plus souvent homolatérale : <span class=\"kw-chiffre\">~30 %</span> après un 1er épisode de PSP, <span class=\"kw-chiffre\">~50 %</span> après un 1er épisode de PSS.</p>\n      <table >\n        <thead>\n          <tr><th>Mesure</th><th>Recommandation</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-ttt\">Sevrage</span> tabagique</td>\n            <td><strong>Systématiquement recommandé</strong> : réduit le risque de PNO spontané et de récidive</td>\n          </tr>\n          <tr>\n            <td>Repos / activité physique</td>\n            <td>Pas de repos ni de limitation des activités physiques (aucune preuve)</td>\n          </tr>\n          <tr>\n            <td>Avion</td>\n            <td>Délai de <span class=\"kw-chiffre\">2-3 semaines</span> après un PNO avant un vol en avion pressurisé</td>\n          </tr>\n          <tr>\n            <td>Plongée subaquatique</td>\n            <td><span class=\"kw-ci\">Contre-indication définitive</span> en cas de lésions bulleuses chez un plongeur ayant un ATCD de PNO spontané, même traité chirurgicalement</td>\n          </tr>\n          <tr>\n            <td>Pleurodèse</td>\n            <td>Symphyse des feuillets pariétal et viscéral après ré-expansion pulmonaire. <strong>Indications :</strong> récidive de PNO ; ou PNO persistant après <span class=\"kw-chiffre\">3-5 jours</span> de <span class=\"kw-ttt\">drainage</span> malgré aspiration douce. <strong>Techniques :</strong> abrasion mécanique (thoracoscopie chirurgicale) ; ou installation d'un produit irritant (talc, par thoracoscopie médicale)</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 75 — Addiction <span class=\"kw-etio\">Tabac</span></em></p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré :</strong> <span class='kw-alerte'>PNO grave</span> = définition <span class='kw-def'>clinique</span> (indépendante de l'importance du décollement) : <span class='kw-alerte'>dyspnée sévère</span> et/ou <span class='kw-alerte'>collapsus tensionnel</span><br><strong>Forme extrême :</strong> <span class='kw-etio'>PNO compressif</span> (<span class='kw-clinique'>fistule broncho-pleurale</span> = valve unidirectionnelle) → pression pleurale positive → <span class='kw-alerte'>tamponnade gazeuse</span> (gêne au retour veineux)<br><strong>1er geste :</strong> <span class='kw-ttt'>évacuation du gaz</span> en <span class=\"kw-alerte\">urgence</span> (<span class='kw-ttt'>exsufflation</span> / <span class='kw-ttt'>drainage</span>)</p>","hospit":"<p><strong>Ambulatoire :</strong> <span class='kw-ttt'>exsufflation</span> bien tolérée, durée d'<span class=\"kw-alerte\">hospitalisation</span> brève ; <span class='kw-etio'>PSP</span> bien toléré et de faible abondance → <span class='kw-ttt'>surveillance</span><br><strong>Hospit :</strong> indication de <span class='kw-ttt'>drainage</span> pleural (<span class='kw-etio'>PSS</span>, grande abondance, mauvaise tolérance)<br><strong>Réa :</strong> <span class='kw-alerte'>PNO grave / compressif</span> ; <span class='kw-alerte'>PNO sous ventilation mécanique</span></p>","redflags":"<ul><li><span class='kw-clinique'>Hypotension</span> (PAS <span class=\"kw-chiffre\">≤ 90 mmHg</span>), <span class='kw-clinique'>tachycardie</span> <span class=\"kw-chiffre\">≥ 120 bpm</span> ou <span class='kw-alerte'>bradycardie</span> (gravité extrême)</li><li><span class='kw-clinique'>Désaturation</span>, <span class='kw-alerte'>détresse respiratoire</span></li><li><span class='kw-alerte'>Signes droits</span> : <span class=\"kw-clinique\">hypotension</span> + <span class='kw-clinique'>turgescence jugulaire</span> (<span class=\"kw-alerte\">défaillance</span> cardiaque droite)</li><li><span class='kw-clinique'>Déviation de la pointe du cœur</span> (déplacement médiastinal)</li><li><span class='kw-alerte'>Arrêt cardiaque</span> au maximum</li><li><span class=\"kw-def\">Terrain</span> : caractère <span class='kw-alerte'>bilatéral</span>, <span class='kw-alerte'>poumon unique</span>, survenue sous <span class='kw-alerte'>ventilation invasive/non-invasive</span>, <span class='kw-etio'>insuffisance respiratoire chronique</span> sous-jacente</li><li><span class=\"kw-imagerie\">RXT</span> — <span class='s-rad'>refoulement controlatéral du médiastin</span>, <span class='s-rad'>hyperclarté bilatérale</span>, <span class='s-rad'>bride</span> (risque <span class=\"kw-etio\">hémorragique</span>), <span class='s-rad'>niveau liquidien</span> (hémopneumothorax)</li></ul>","principes":"<p>Choix guidé par la tolérance, l'abondance et le <span class=\"kw-def\">terrain</span> ; approche moins invasive privilégiant <span class=\"kw-clinique\">les</span> drains de petit calibre.</p><p><strong>Choix guidé par 3 questions</strong></p><ul><li>Bonne tolérance ? (<span class='kw-clinique'>dyspnée</span>, <span class='kw-bio'><span class=\"kw-bio\">SpO2</span></span>)</li><li>Grande abondance ? (décollement <span class='kw-chiffre'><span class=\"kw-chiffre\">≥ 2 cm</span></span> au hile, sur la ligne axillaire)</li><li>Cause / <span class=\"kw-def\">terrain</span> : <span class='kw-etio'>PSP</span>, <span class='kw-etio'>PSS</span>, <span class='kw-etio'>PNO traumatique</span></li></ul><p><strong><span class=\"kw-def\">Surveillance</span></strong></p><p>Indiquée : <span class='kw-etio'>PSP</span> bien toléré et de faible abondance ; <span class='kw-etio'>PNO traumatique</span> bien toléré (hors ventilation)</p><ul><li>Le PNO se résorbe spontanément (~<span class='kw-chiffre'><span class=\"kw-chiffre\">1 %</span> du volume/jour</span>)</li><li>Pas d'intervention sur <span class=\"kw-clinique\">les</span> PNO bien tolérés, sous <span class=\"kw-def\">surveillance</span></li></ul><p><strong>Exsufflation (<span class=\"kw-ttt\">ponction</span>)</strong></p><p>1re intention du <span class='kw-etio'>PSP</span> mal toléré ou de grande abondance → <span class='kw-ttt'>drain de petit calibre</span> si échec</p><ul><li><span class='kw-ttt'>Anesthésie locale</span> + petit cathéter, <span class='kw-ttt'>voie thoracique antérieure</span> (2e-3e EIC, en dehors de la ligne médio-claviculaire)</li><li>Aspiration manuelle (<span class='kw-ttt'>seringue <span class=\"kw-chiffre\">50 mL</span></span>) ou système d'aspiration douce ; contrôle radiographique</li><li>Taux de succès ~<span class='kw-chiffre'><span class=\"kw-chiffre\">50 %</span></span>, indépendant de la taille du PNO</li></ul><p><strong><span class=\"kw-ttt\">Drainage</span> pleural</strong></p><p>Indications : <span class='kw-etio'>PSS</span> (sauf tout petit décollement) ; <span class='kw-etio'>PNO traumatique</span> (sous ventilation ou mal toléré/grande abondance) ; échec d'exsufflation</p><ul><li><span class='kw-ttt'>Voie antérieure</span> (2e-3e EIC) ou <span class='kw-ttt'>axillaire</span> (triangle de sécurité, 4e-5e EIC)</li><li>Percutané (<span class='kw-ttt'>drain en queue de cochon</span>) ou chirurgical</li><li>Évacuation active : <span class='kw-ttt'>aspiration douce</span> <span class='kw-chiffre'>-5 à -20 mmHg</span> ; ou passive : <span class='kw-ttt'>siphonage</span> / valve unidirectionnelle</li><li>Bilan pré-geste (hors <span class=\"kw-alerte\">urgence</span>) : <span class='kw-bio'>hémostase</span> + <span class='kw-bio'>groupe sanguin</span></li><li>Ablation après réexpansion complète, en l'absence de fuite persistante</li></ul>","suivi":"<p><strong>Contrôle :</strong> <span class='kw-imagerie'><span class=\"kw-imagerie\">RXT</span> de contrôle</span> après <span class=\"kw-ttt\">ponction</span>/drainage (recherche de complication <span class=\"kw-etio\">iatrogène</span>, bonne position du drain)<br><strong>Récidive :</strong> <span class='kw-etio'>PSP</span> ~<span class='kw-chiffre'><span class=\"kw-chiffre\">30 %</span></span> ; <span class='kw-etio'>PSS</span> ~<span class='kw-chiffre'><span class=\"kw-chiffre\">50 %</span></span><br><strong><span class=\"kw-ttt\">Sevrage</span> tabagique :</strong> systématique (risque de PNO et de récidive)<br><strong>Avion :</strong> délai <span class='kw-chiffre'><span class=\"kw-chiffre\">2-3 semaines</span></span> après un PNO<br><strong>Plongée :</strong> <span class='kw-ci'><span class=\"kw-ci\">contre-indication</span> définitive</span> si lésions bulleuses et ATCD de PNO spontané (même opéré)<br><strong>Pleurodèse :</strong> <span class='kw-ttt'>symphyse pleurale</span> si récidive ou PNO persistant après <span class='kw-chiffre'>3-5 j</span> de <span class=\"kw-ttt\">drainage</span> malgré aspiration douce</p>"},"liensGlobaux":[{"href":"https://cep-1f48c.kxcdn.com/wp-content/uploads/2023/07/ITEM_360_PNEUMOTHORAX_2023.pdf","label":"Collège (CEP) — Item 360 pneumothorax 2023"},{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/26.%20%C3%89panchements%20pleuraux%20liquidiens%20et%20pneumothorax.pdf","label":"CeMIR — 26. épanchements pleuraux liquidiens et pneumothorax"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"PNO confirmé — Clinique + RXT de face, debout, en inspiration","detail":"<h4>CAT — Traitement du pneumothorax — Choix guidé par 3 questions : tolérance, abondance (<span class=\"kw-chiffre\">≥ 2 cm</span>) et <span class=\"kw-def\">terrain</span> (PSP / PSS / traumatique)</h4>","branches":[{"to":"q-grave","label":"PNO confirmé","color":"blue"}]},{"id":"q-grave","kind":"decision","label":"PNO grave / compressif ? — Dyspnée sévère, collapsus tensionnel, signes droits (TJ)","branches":[{"to":"t-compressif","label":"Oui — collapsus / détresse","color":"red"},{"to":"q-toler","label":"Non","color":"green"}]},{"id":"t-compressif","kind":"terminal","label":"Décompression en urgence","color":"red","detail":"<h4>Conduite</h4><ul><li><span class='s-grav'><span class=\"kw-alerte\">Urgence</span> vitale</span> : évacuation du gaz sans délai</li><li><span class='s-med'>Exsufflation</span> puis <span class='s-med'><span class=\"kw-ttt\">drainage</span> pleural</span></li><li>Orientation <span class='s-grav'><span class=\"kw-alerte\">réanimation</span></span></li></ul><h4>Contexte</h4><ul><li><span class='s-etio'>PNO compressif</span> = valve unidirectionnelle → pression pleurale positive</li><li><span class='s-grav'><span class=\"kw-alerte\">Tamponnade</span> gazeuse</span> : chute tensionnelle + <span class=\"kw-ci\">insuffisance cardiaque</span> droite (<span class='s-clin'>TJ</span>)</li></ul>"},{"id":"q-toler","kind":"decision","label":"Bien toléré ET de faible abondance ? — Décollement &lt; 2 cm au hile sur la ligne axillaire","branches":[{"to":"q-terrain-evac","label":"Non — mal toléré ou ≥ 2 cm","color":"amber"},{"to":"q-terrain-surv","label":"Oui — bien toléré, &lt; 2 cm","color":"green"}]},{"id":"q-terrain-evac","kind":"decision","label":"Quel terrain ? — PNO mal toléré ou ≥ 2 cm","branches":[{"to":"t-psp-evac","label":"PSP (spontané primaire)","color":"amber"},{"to":"t-pss-evac","label":"PSS (spontané secondaire)","color":"amber"},{"to":"t-trauma-evac","label":"Traumatique","color":"amber"}]},{"id":"t-psp-evac","kind":"terminal","label":"Exsufflation manuelle (± drain si échec)","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class='s-etio'>PSP</span> mal toléré ou <span class=\"kw-chiffre\">≥ 2 cm</span></li><li>1. <span class='s-med'>Exsufflation manuelle</span> (voie antérieure)</li><li>2. Si échec : <span class='s-med'>drain de petit calibre</span></li><li><span class='s-imag'><span class=\"kw-imagerie\">RXT</span> de contrôle</span> après le geste</li></ul>"},{"id":"t-pss-evac","kind":"terminal","label":"Drain de petit calibre","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class='s-etio'>PSS</span> mal toléré ou <span class=\"kw-chiffre\">≥ 2 cm</span></li><li><span class='s-med'>Drain de petit calibre</span> (aspiration douce ou siphonage)</li><li><span class='s-imag'><span class=\"kw-imagerie\">RXT</span> de contrôle</span> après le geste</li></ul>"},{"id":"t-trauma-evac","kind":"terminal","label":"Drainage pleural","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class='s-etio'>PNO traumatique</span> mal toléré ou <span class=\"kw-chiffre\">≥ 2 cm</span></li><li><span class='s-med'><span class=\"kw-ttt\">Drainage</span> pleural</span></li><li><span class='s-imag'><span class=\"kw-imagerie\">RXT</span> de contrôle</span> après le geste</li></ul>"},{"id":"q-terrain-surv","kind":"decision","label":"Quel terrain ? — PNO bien toléré et de faible abondance","branches":[{"to":"t-psp-surv","label":"PSP","color":"green"},{"to":"t-pss-surv","label":"PSS","color":"amber"},{"to":"t-trauma-surv","label":"Traumatique","color":"green"}]},{"id":"t-psp-surv","kind":"terminal","label":"Surveillance","color":"green","detail":"<h4>Conduite</h4><ul><li><span class='s-etio'>PSP</span> bien toléré et de faible abondance</li><li><span class='s-med'><span class=\"kw-def\">Surveillance</span></span> (résorption spontanée ~<span class='s-nb'><span class=\"kw-chiffre\">1 %</span>/jour</span>)</li><li>Pas d'intervention sur le PNO bien toléré</li></ul>"},{"id":"t-pss-surv","kind":"terminal","label":"Drain (sauf tout petit décollement)","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class='s-etio'>PSS</span> bien toléré et de faible abondance</li><li><span class='s-med'>Drain</span> — sauf si tout petit décollement</li></ul>"},{"id":"t-trauma-surv","kind":"terminal","label":"Surveillance (drain si ventilation)","color":"green","detail":"<h4>Conduite</h4><ul><li><span class='s-etio'>PNO traumatique</span> bien toléré et de faible abondance</li><li><span class='s-med'><span class=\"kw-def\">Surveillance</span></span></li><li>Si patient sous <span class='s-grav'>ventilation assistée</span> : <span class='s-med'>drain</span></li></ul>"}]},"cards":[{"i":"77dc5d373c89","n":360,"o":"360-1","u":"Définition","t":"Connaître la définition du pneumothorax","q":"Quel est l'impact de la présence d'air dans l'espace pleural en cas de pneumothorax ?","a":"<p>La présence d'air dans l'espace pleural entraîne un <strong>collapsus partiel ou complet du poumon</strong> et sa <strong>rétraction sur le hile</strong>. Le poumon se désolidarise alors de la paroi thoracique.</p>"},{"i":"bc7a9943cb7e","n":360,"o":"360-1","u":"Définition","t":"Connaître la définition du pneumothorax","q":"Quel est le rôle de l'espace pleural et de la pression négative dans la fonction pulmonaire normale ?","a":"<p>L'espace pleural, rendu virtuel par la <strong>pression négative</strong> qui y règne (le « vide pleural »), assure le <strong>maintien de l'expansion pulmonaire</strong> en conditions normales.</p>"},{"i":"c4ce425e27a8","n":360,"o":"360-1","u":"Définition","t":"Connaître la définition du pneumothorax","q":"Quelle est la définition du pneumothorax ?","a":"<p>Le pneumothorax (PNO) est défini par la présence d'<strong>air</strong> dans l'<strong>espace pleural</strong>, ce qui constitue un <strong>épanchement pleural gazeux</strong>.</p>"},{"i":"143ba1f1913d","n":360,"o":"360-3","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic positif et du diagnostic différentiel d’un pneumothorax","q":"Quelle est la principale difficulté diagnostique différentielle du pneumothorax, notamment chez les patients atteints de BPCO ?","a":"<p>Le différentiel le plus difficile du pneumothorax, en particulier chez les patients atteints de BPCO sévère, est la distinguer des <strong>bulles géantes d'emphysème</strong>. Ces dernières peuvent être confondues à tort avec un pneumothorax en raison d'une hyperclarté thoracique. Il faut rechercher le <strong>signe du raccordement</strong> sur la radiographie et la TDM thoracique avant tout drainage. Une gazométrie artérielle peut montrer une hypoxémie associée à une hypocapnie (effet shunt).</p>"},{"i":"63a536fe165a","n":360,"o":"360-3","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic positif et du diagnostic différentiel d’un pneumothorax","q":"Quels sont les facteurs favorisants et anamnestiques à rechercher lors de la suspicion d'un pneumothorax ?","a":"<p>Les facteurs favorisants à rechercher à l'interrogatoire en cas de suspicion de pneumothorax sont :</p><ul><li>Un <strong>antécédent de pneumothorax</strong> (récidive dans près d'<strong>un tiers</strong> des cas).</li><li>Un <strong>tabagisme actif</strong>.</li><li>Des <strong>efforts inspiratoires lors du sniff de cocaïne</strong>.</li><li>Des activités comme les <strong>vols aériens</strong> et la <strong>plongée subaquatique</strong>, qui peuvent majorer un PNO préexistant mais n'en créent pas de novo.</li></ul>"},{"i":"8bfeb01ccdc3","n":360,"o":"360-3","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic positif et du diagnostic différentiel d’un pneumothorax","q":"Quels sont les signes fonctionnels évocateurs d'un pneumothorax ?","a":"<p>Les signes fonctionnels d'un pneumothorax sont :</p><ul><li>Une <strong>douleur thoracique</strong> : de début <strong>brutal</strong>, souvent au <strong>repos</strong>, type <strong>coup de poignard</strong>, homolatérale au pneumothorax, rythmée par la respiration et au changement de position. Elle s'estompe souvent rapidement.</li><li>Une <strong>dyspnée</strong> : inconstante et d'intensité variable.</li><li>Une <strong>toux sèche irritative</strong>.</li></ul>"},{"i":"fc4e62630007","n":360,"o":"360-3","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic positif et du diagnostic différentiel d’un pneumothorax","q":"Comment l'examen physique d'un patient avec pneumothorax se présente-t-il spécifiquement ?","a":"<p>L'examen physique d'un patient avec pneumothorax révèle un <strong>syndrome d'épanchement gazeux</strong> :</p><ul><li>À l'<strong>inspection</strong> : hémithorax normal, ou distendu et <strong>moins mobile</strong> (diminution de l'ampliation thoracique).</li><li>À la <strong>palpation</strong> : <strong>abolition des vibrations vocales</strong> ; possible <strong>emphysème sous-cutané</strong> (rare).</li><li>À la <strong>percussion</strong> : <strong>tympanisme</strong>.</li><li>À l'<strong>auscultation</strong> : <strong>diminution ou abolition du murmure vésiculaire</strong>.</li></ul>"},{"i":"1c9c114776b9","n":360,"o":"360-4","u":"Diagnostic positif","t":"Connaître la sémiologie radiologique du pneumothorax","q":"Comment se caractérise radiologiquement un pneumothorax incomplet ?","a":"<p>Un pneumothorax incomplet se caractérise par une <strong>hyperclarté</strong> avec disparition du parenchyme pulmonaire, prédominant au niveau <strong>apical</strong>.</p>"},{"i":"1efb39367056","n":360,"o":"360-4","u":"Diagnostic positif","t":"Connaître la sémiologie radiologique du pneumothorax","q":"Dans quelles situations un scanner thoracique (TDM thoracique non injectée) est-il indiqué pour le diagnostic de pneumothorax ?","a":"<p>Une TDM thoracique non injectée est indiquée en cas de <strong>doute radiologique</strong>, de <strong>forme secondaire</strong> ou de <strong>forme traumatique</strong> de pneumothorax. Elle n'est pas systématique.</p>"},{"i":"27c0b6678423","n":360,"o":"360-4","u":"Diagnostic positif","t":"Connaître la sémiologie radiologique du pneumothorax","q":"Quels sont les signes radiologiques de gravité d'un pneumothorax ?","a":"<ul><li><strong>Refoulement controlatéral du médiastin</strong>.</li><li><strong>Hyperclarté bilatérale</strong>.</li><li>Présence d'une <strong>bride</strong> (avec risque hémorragique).</li><li>Présence d'un <strong>niveau liquidien</strong> (avec risque d'hémopneumothorax).</li><li>Anomalie du <strong>parenchyme pulmonaire sous-jacent</strong>.</li></ul>"},{"i":"7336b85d460c","n":360,"o":"360-4","u":"Diagnostic positif","t":"Connaître la sémiologie radiologique du pneumothorax","q":"Quels sont les signes radiologiques d'un pneumothorax complet ?","a":"<ul><li><strong>Rétraction du parenchyme pulmonaire</strong> autour du hile.</li><li><strong>Abaissement de la coupole diaphragmatique</strong> homolatérale.</li><li><strong>Élargissement des espaces intercostaux</strong>.</li><li>Possibilité d'une <strong>réaction liquidienne</strong> de faible volume.</li></ul>"},{"i":"e2df334a3066","n":360,"o":"360-4","u":"Diagnostic positif","t":"Connaître la sémiologie radiologique du pneumothorax","q":"Quel est l'intérêt de l'échographie pleurale dans le diagnostic de pneumothorax ?","a":"<p>L'échographie pleurale permet un <strong>diagnostic immédiat</strong> d'un pneumothorax directement <strong>au lit du patient</strong>.</p>"},{"i":"f57265c8412c","n":360,"o":"360-4","u":"Diagnostic positif","t":"Connaître la sémiologie radiologique du pneumothorax","q":"Quelles sont les modalités réglementaires pour la réalisation d'une radiographie thoracique en cas de suspicion de pneumothorax ?","a":"<p>La radiographie thoracique doit être réalisée de <strong>face</strong>, en position <strong>debout</strong> et en <strong>inspiration</strong>. La radiographie en expiration n'est plus recommandée.</p>"},{"i":"6078df59b61f","n":360,"o":"360-5","u":"Contenu multimédia","t":"Radiographie de face d’un pneumothorax spontané d’abondance moyenne","q":"Quelle est la sémiologie radiologique attendue d'un pneumothorax d'abondance moyenne sur une radiographie de thorax de face ?","a":"<p>On observe une <strong>hyperclarté de l'hémithorax</strong> avec <strong>disparition de la trame vasculaire pulmonaire</strong> en périphérie. Une <strong>ligne pleurale visible</strong> matérialise la limite externe du poumon partiellement collabé.</p>"},{"i":"81b51efeec69","n":360,"o":"360-5","u":"Contenu multimédia","t":"Radiographie de face d’un pneumothorax spontané d’abondance moyenne","q":"Quels sont les éléments sémiologiques clés d'un pneumothorax droit d'abondance moyenne sur une radiographie de thorax de face ?","a":"<p>Les éléments clés sont un <strong>croissant clair avasculaire périphérique</strong> et une <strong>ligne pleurale bordante</strong> (correspondant à la plèvre viscérale décollée de la plèvre pariétale).</p>"},{"i":"f97adb0ae251","n":360,"o":"360-5","u":"Contenu multimédia","t":"Radiographie de face d’un pneumothorax spontané d’abondance moyenne","q":"Comment un pneumothorax de 'grande taille' est-il arbitrairement défini sur radiographie de thorax ?","a":"<p>Un pneumothorax de 'grande taille' est arbitrairement défini par un <strong>décollement sur toute la hauteur de la ligne axillaire</strong>, d'une <strong>largeur ≥ 2 cm au niveau du hile</strong>.</p>"},{"i":"13b3f7d0502f","n":360,"o":"360-6","u":"Contenu multimédia","t":"Radiographie de thorax d’un pneumothorax complet","q":"À l'examen d'une radiographie thoracique avec un pneumothorax complet, quel signe radiologique doit faire rechercher systématiquement un caractère compressif ?","a":"Face à un pneumothorax complet, la <strong>déviation médiastinale controlatérale</strong> (refoulement controlatéral du médiastin) est un signe radiologique de gravité indiquant un caractère compressif."},{"i":"1f5fdbf7763b","n":360,"o":"360-6","u":"Contenu multimédia","t":"Radiographie de thorax d’un pneumothorax complet","q":"Quels sont les signes radiologiques clés d'un pneumothorax complet sur une radiographie thoracique de face ?","a":"Les signes radiologiques d'un pneumothorax complet incluent :\n<ul>\n<li>Un <strong>poumon entièrement collabé</strong>, rétracté en moignon autour du hile.</li>\n<li>Une <strong>hyperclarté de l'ensemble de l'hémithorax</strong> atteint.</li>\n<li>Un <strong>abaissement de la coupole diaphragmatique</strong> homolatérale.</li>\n<li>Un <strong>élargissement des espaces intercostaux</strong>.</li>\n</ul>"},{"i":"2b2ed09187c5","n":360,"o":"360-7","u":"Étiologies","t":"Connaître les éléments du diagnostic étiologique d’un pneumothorax : pneumothorax traumatique, pneumothorax spontané primaire, pneumothorax spontané secondaire","q":"Quelles sont les causes possibles d'un pneumothorax traumatique ?","a":"<p>Un pneumothorax traumatique peut résulter de :</p><ul><li>Un <strong>traumatisme ouvert</strong> du thorax (arme blanche, arme à feu).</li><li>Un <strong>traumatisme fermé</strong> du thorax : fracture de côte, blast pulmonaire (hyperpression thoracique).</li><li>Des causes <strong>iatrogènes</strong> lors de gestes invasifs thoraciques : ponction transthoracique, ponction pleurale, pose de voie veineuse centrale (jugulaire, sous-clavière), cœlioscopie.</li></ul>"},{"i":"c66ca5f77307","n":360,"o":"360-7","u":"Étiologies","t":"Connaître les éléments du diagnostic étiologique d’un pneumothorax : pneumothorax traumatique, pneumothorax spontané primaire, pneumothorax spontané secondaire","q":"Quelles sont les étiologies d'un pneumothorax spontané secondaire ?","a":"<p>Un pneumothorax spontané secondaire (PSS) est causé par la rupture d'un poumon pathologique. Les principales étiologies sont :</p><ul><li>La <strong>BPCO</strong> (cause la plus fréquente).</li><li>Plus rarement : asthme sévère, <strong>mucoviscidose</strong>, pneumocystose.</li><li>Pathologies pulmonaires : maladies interstitielles diffuses (PID), lésions néoplasiques, bulles d'emphysème, lésions kystiques ou nécrosantes, pneumonie abcédée.</li></ul>"},{"i":"d3f28b959af4","n":360,"o":"360-7","u":"Étiologies","t":"Connaître les éléments du diagnostic étiologique d’un pneumothorax : pneumothorax traumatique, pneumothorax spontané primaire, pneumothorax spontané secondaire","q":"Quels sont les facteurs évocateurs d'un pneumothorax spontané primaire ?","a":"<p>Un pneumothorax spontané primaire (PSP) survient typiquement chez un <strong>adulte jeune</strong> (< 35 ans), de sexe masculin, longiligne et de grande taille. Le <strong>tabagisme</strong> est un facteur de risque majeur, retrouvé dans les trois quarts des cas.</p>"},{"i":"027b2422e18f","n":360,"o":"360-8","u":"Identifier une urgence","t":"Connaître les éléments du diagnostic de gravité d’un pneumothorax","q":"Quel est le mécanisme physiopathologique du pneumothorax compressif, forme la plus grave de pneumothorax ?","a":"<p>Le pneumothorax compressif est causé par une <strong>fistule broncho-pleurale</strong> agissant comme une <strong>valve unidirectionnelle</strong>, où l'air entre dans la plèvre à l'inspiration mais ne peut en ressortir à l'expiration. Cela entraîne une pression pleurale positive qui gêne le retour veineux (« <strong>tamponnade gazeuse</strong> ») provoquant une chute tensionnelle et des signes d'insuffisance cardiaque droite.</p>"},{"i":"7032491b1a9f","n":360,"o":"360-8","u":"Identifier une urgence","t":"Connaître les éléments du diagnostic de gravité d’un pneumothorax","q":"Quels sont les critères de gravité d'un pneumothorax liés au terrain ou au contexte ?","a":"<ul><li>Caractère <strong>bilatéral</strong></li><li>Survenue sur <strong>poumon unique</strong></li><li>Survenue sous <strong>ventilation invasive ou non invasive</strong></li><li><strong>Insuffisance respiratoire chronique</strong> sous-jacente</li></ul>"},{"i":"7bf4b17b7917","n":360,"o":"360-8","u":"Identifier une urgence","t":"Connaître les éléments du diagnostic de gravité d’un pneumothorax","q":"Quand faut-il systématiquement évoquer un pneumothorax sous ventilation mécanique chez un patient de réanimation ?","a":"<ul><li>Devant toute <strong>augmentation brutale des pressions d'insufflation</strong> du respirateur</li><li>Devant tout <strong>collapsus brutal</strong> sous ventilation assistée (suggérant un PNO compressif)</li><li>Au décours d'une tentative de <strong>pose de voie veineuse sous-clavière</strong></li></ul>"},{"i":"abc1ff2e3224","n":360,"o":"360-8","u":"Identifier une urgence","t":"Connaître les éléments du diagnostic de gravité d’un pneumothorax","q":"Comment est définie la gravité d'un pneumothorax selon les critères cliniques ?","a":"<p>La gravité d'un pneumothorax est définie par la présence d'une <strong>dyspnée sévère</strong> et/ou un <strong>collapsus tensionnel</strong>. Elle ne dépend pas de l'importance du décollement pleural sur la radiographie.</p>"},{"i":"cdb5183f00ed","n":360,"o":"360-8","u":"Identifier une urgence","t":"Connaître les éléments du diagnostic de gravité d’un pneumothorax","q":"Quels sont les signes cliniques de gravité spécifiques d'un pneumothorax ?","a":"<ul><li><strong>Hypotension</strong> (PAS &le; 90 mmHg)</li><li><strong>Tachycardie &ge; 120 bpm</strong>, ou <strong>bradycardie</strong> (gravité extrême)</li><li><strong>Désaturation</strong>, <strong>détresse respiratoire</strong></li><li><strong>Signes droits</strong> : hypotension artérielle + turgescence jugulaire, signant une défaillance cardiaque droite</li><li><strong>Déviation de la pointe du cœur</strong> (déplacement médiastinal)</li><li><strong>Arrêt cardiaque</strong> (au maximum de la gravité)</li></ul>"},{"i":"991dbce11f64","n":360,"o":"360-9","u":"Prise en charge","t":"Connaître les grands principes de l’exsufflation pleurale et ses indications","q":"Quels sont les trois critères déterminant la décision thérapeutique face à un pneumothorax ?","a":"<p>La décision thérapeutique pour un pneumothorax repose sur trois questions clés :</p><ul><li>Le PNO est-il <strong>bien toléré</strong> (évaluation de la dyspnée, de la SpO2) ?</li><li>Est-il de <strong>grande abondance</strong> (décollement ≥ 2 cm) ?</li><li>Quelle est sa <strong>cause/le terrain</strong> (PNO spontané primaire, PNO spontané secondaire, PNO traumatique) ?</li></ul>"},{"i":"a36401d3b2d5","n":360,"o":"360-9","u":"Prise en charge","t":"Connaître les grands principes de l’exsufflation pleurale et ses indications","q":"Qu'est-ce que l'exsufflation pleurale et quelles sont ses indications principales pour le pneumothorax ?","a":"<p>L'exsufflation pleurale est une <strong>ponction thoracique</strong> réalisée sous anesthésie locale, visant à évacuer l'air de la plèvre. Elle consiste à introduire un <strong>petit cathéter</strong> (par voie thoracique antérieure, patient semi-assis ou en décubitus dorsal) et à effectuer une <strong>aspiration manuelle à la seringue de 50 mL</strong> ou avec un système d'aspiration douce.</p><p>Ses indications principales sont :</p><ul><li>Comme <strong>seul traitement des PNO spontanés</strong> (selon le CEP).</li><li>En cas de <strong>mauvaise tolérance</strong> ou de <strong>décollement ≥ 2 cm</strong> sur l'ensemble de la ligne axillaire (selon le MIR).</li></ul><p>Elle est bien tolérée et peut être réalisée en ambulatoire. En cas d'échec (taux de succès d'environ 50%), un drain pleural de petit calibre est posé en seconde intention.</p>"},{"i":"a759a4d26332","n":360,"o":"360-9","u":"Prise en charge","t":"Connaître les grands principes de l’exsufflation pleurale et ses indications","q":"Quelles sont les voies d'abord recommandées pour l'exsufflation/drainage d'un pneumothorax et les précautions à prendre ?","a":"<p>Deux voies d'abord principales sont utilisées :</p><ul><li><strong>Voie antérieure</strong> : <strong>2<sup>e</sup> ou 3<sup>e</sup> espace intercostal</strong>, en dehors de la ligne médio-claviculaire pour éviter l'<strong>artère mammaire interne</strong>.</li><li><strong>Voie axillaire</strong> (triangle de sécurité) : <strong>4<sup>e</sup> ou 5<sup>e</sup> espace intercostal</strong>, sur la ligne axillaire moyenne. Il ne faut <strong>jamais piquer sous la ligne mamelonnaire</strong> pour éviter le risque de plaie diaphragmatique et de blessures d'organes abdominaux.</li></ul>"}]};